public TreeNode constructTreeWithInOrderAndPreOrder(int[] pre, int[] in, int pre_s, int pre_e, int in_s, int in_e) {
    if (pre_s > pre_e) {
        return null;
    }
    int rootVal = pre[pre_s];
    TreeNode root = new TreeNode(rootVal);
    int index = -1;
    for (int i = in_s; i <= in_e; i++) {
