    root.left = constructTreeWithInOrderAndPreOrder(pre, in, pre_s + 1, r, in_s, index - 1);
    root.right = constructTreeWithInOrderAndPreOrder(pre, in, r + 1, pre_e, index + 1, in_e);

    return root;
}

public ArrayList<Integer> serialize(TreeNode A) {
    ArrayList<Integer> ans = new ArrayList<Integer>();
    Queue<TreeNode> q = new LinkedList<>();
    q.add(A);
    while (q.size() != 0) {
        TreeNode cur = q.peek();
        q.remove();
        if (cur == null) {
            ans.add(-1);
            continue;
        }
        ans.add(cur.val);
        q.add(cur.left);
        q.add(cur.right);
    }
    return ans;
}

public TreeNode deserialize(ArrayList<Integer> A) {
    if (A == null || A.isEmpty() || A.get(0) == -1) {
        return null;
    }

    TreeNode root = new TreeNode(A.get(0));
    Queue<TreeNode> q = new LinkedList<>();
    q.add(root);
    int i = 1;

    while (!q.isEmpty() && i < A.size()) {
        TreeNode cur = q.poll();

        if (i < A.size()) {
            int leftVal = A.get(i++);
            if (leftVal != -1) {
                cur.left = new TreeNode(leftVal);
                q.add(cur.left);
            }
        }

        if (i < A.size()) {
            int rightVal = A.get(i++);
            if (rightVal != -1) {
                cur.right = new TreeNode(rightVal);
                q.add(cur.right);
            }
        }
    }

    return root;
}

