public boolean isValidBST(TreeNode root) {
    return isValidBST(root, Long.MIN_VALUE, Long.MAX_VALUE);
}

public boolean isValidBST(TreeNode A, long min, long max) {
    if (A == null) {
        return true;
    }
    if (A.val > min && A.val < max) {
        return (isValidBST(A.left, min, (long) (A.val)) && 
                isValidBST(A.right, (long) (A.val), max));
    }
    return false;
}

public TreeNode sortedArrayToBST(int[] nums) {
    return convert(nums, 0, nums.length - 1);
}

public TreeNode convert(int[] nums, int l, int r) {
    if (l > r) {
        return null;
    }
    int mid = (l + r) / 2;
    TreeNode root = new TreeNode(nums[mid]);
    root.left = convert(nums, l, mid - 1);
    root.right = convert(nums, mid + 1, r);
    return root;
}

public TreeNode deleteNode(TreeNode root, int B) {
    if (root == null) {
        return null;
    }

    if (B < root.val) {
        root.left = deleteNode(root.left, B);
    } else if (B > root.val) {
        root.right = deleteNode(root.right, B);
    } else {
        if (root.left == null) {
            return root.right;
        }
        if (root.right == null) {
            return root.left;
        }

        TreeNode pred = findMax(root.left);
        root.val = pred.val;
        root.left = deleteNode(root.left, pred.val);
    }
    return root;
}

private TreeNode findMax(TreeNode node) {
    while (node.right != null) {
        node = node.right;
    }
    return node;
}

