public int searchInABST(TreeNode A, int B) {
    if (A == null) {
        return 0;
    }
    if (A.val == B) {
        return 1;
    }
    if (A.val > B) {
        return searchInABST(A.left, B);
    } else {
        return searchInABST(A.right, B);
    }
}

public int twoSumBST(TreeNode A, int B) {
    ArrayList<Integer> list = new ArrayList<>();
    inorder(A, list);
    int left = 0, right = list.size() - 1;
    while (left < right) {
        int sum = list.get(left) + list.get(right);
        if (sum == B) {
            return 1;
        }
        if (sum < B) {
            left++;
        } else {
            right--;
        }
    }
    return 0;
}

private void inorder(TreeNode root, ArrayList<Integer> list) {
    if (root == null) {
        return;
    }
    inorder(root.left, list);
    list.add(root.val);
    inorder(root.right, list);
}

public int twoSumBSTHashSet(TreeNode A, int B) {
    HashSet<Integer> set = new HashSet<>();
    return search(A, B, set);
}

private int search(TreeNode root, int B, HashSet<Integer> set) {
    if (root == null) {
        return 0;
    }
    if (set.contains(B - root.val)) {
        return 1;
    }
    set.add(root.val);
    int left = search(root.left, B, set);
    if (left == 1) {
        return 1;
    }
    return search(root.right, B, set);
}

