public String checkBSTOneChild(int[] A) {
    int N = A.length;
    for (int i = 0; i < N - 1; i++) {
        int current = A[i];
        int next = A[i + 1];
        boolean isLeft = next < current;

        for (int j = i + 1; j < N; j++) {
            if (isLeft && A[j] > current) {
                return "NO";
            }
            if (!isLeft && A[j] < current) {
                return "NO";
            }
        }
    }
    return "YES";
}

